const raw = $input.first().json;
const body = raw.body || raw;
const payload = body.payload || {};
const branding = payload.branding || {};
function orgName() {
  const n = branding.nameI18n || {};
  return n.fr || n.en || n.pt || 'KonselyaVisa';
}
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}
function brandMail(title, bodyHtml, bodyTextLines) {
  const color = branding.brandColor || '#1780F2';
  const name = orgName();
  const logo = branding.logoUrl
    ? '<img src="' + esc(branding.logoUrl) + '" alt="' + esc(name) + '" style="max-height:48px;max-width:180px;" />'
    : '<strong style="color:' + color + ';font-size:18px;">' + esc(name) + '</strong>';
  const html = '<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;color:#1a1a1a;margin:0;padding:0;">' +
    '<div style="border-top:4px solid ' + color + ';padding:24px;max-width:560px;">' +
    '<div style="margin-bottom:16px;">' + logo + '</div>' +
    '<h1 style="font-size:18px;color:' + color + ';margin:0 0 12px;">' + esc(title) + '</h1>' +
    bodyHtml +
    '<p style="margin-top:24px;font-size:12px;color:#666;">n8n orchestre autour de l\'état Spring Boot — aucune décision métier ici.</p>' +
    '</div></body></html>';
  const text = [name, '', ...bodyTextLines, '', "n8n n'applique aucune règle métier."].join('\n');
  return { subject: '[' + name + '] ' + title, html, text };
}

const checklist = Array.isArray(payload.documentChecklist) ? payload.documentChecklist : [];
const lines = checklist.map((item) => {
  const labels = item.labelI18n || {};
  const label = labels.fr || labels.en || labels.pt || item.code;
  const flag = item.required === false ? 'optionnel' : 'requis';
  return '- [' + flag + '] ' + item.code + ': ' + label;
});
const reference = payload.reference || body.aggregateId || '';
const title = 'Checklist documents ' + reference;
const bodyHtml = '<p>Dossier créé — checklist documentaire figée à la création (état Spring Boot).</p>' +
  '<p><strong>Référence:</strong> ' + esc(reference) + '<br/>' +
  '<strong>Organisation:</strong> ' + esc(body.organizationId || '') + '</p>' +
  '<ul>' + (checklist.length
    ? checklist.map((item) => {
        const labels = item.labelI18n || {};
        const label = labels.fr || labels.en || labels.pt || item.code;
        const flag = item.required === false ? 'optionnel' : 'requis';
        return '<li>[' + esc(flag) + '] <code>' + esc(item.code) + '</code>: ' + esc(label) + '</li>';
      }).join('')
    : '<li>(aucune pièce listée)</li>') + '</ul>' +
  '<p>Consultez le portail pour déposer les pièces.</p>';
const mail = brandMail(title, bodyHtml, [
  'Dossier créé — checklist documentaire figée à la création (état Spring Boot).',
  '',
  'Référence: ' + reference,
  'Organisation: ' + (body.organizationId || ''),
  'Événement: CASE_CREATED',
  '',
  ...(lines.length ? lines : ['- (aucune pièce listée)']),
  '',
  'Consultez le portail pour déposer les pièces.'
]);
return [{ json: mail }];

